with base as (select id, reading_ts, temp_c, humidity, pressure, status_bits, case when pressure >= 1025 then 'High' when pressure >= 1002 then 'Medium' else 'Low' end as pressure_tier from device_readings where reading_ts >= to_timestamp('2025-09-01 03:00:00') and temp_c < 39) select id, reading_ts, temp_c, humidity, pressure, status_bits, sum(status_bits) over (partition by date_trunc('month', reading_ts)) as reading_ts_period_sum_status_bits, last_value(pressure) ignore nulls over (order by humidity, id rows between unbounded preceding and current row) as last_known_pressure, ntile(4) over (order by pressure, id) as pressure_bucket, sum(pressure) over (order by humidity, id rows between unbounded preceding and current row) as cumulative_pressure, rank() over (order by temp_c nulls first) as temp_c_rank from base;
